      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class ScalablePerformanceManager : MonoBehaviour
{
    [Header("Ajustes de Renderizacao")]
    [SerializeField] private bool habilitarDynamicResolution = true;
    [SerializeField] private float targetFrameRate = 60f;
    [SerializeField] private float minScaleFactor = 0.70f;
    [SerializeField] private float maxScaleFactor = 1.0f;
    [SerializeField] private float escalaShadowDistance = 40f;

    private float currentScale = 1.0f;
    private float targetFrameTime;

    private void Awake()
    {
        Application.targetFrameRate = Mathf.RoundToInt(targetFrameRate);
        targetFrameTime = 1.0f / targetFrameRate;
        QualitySettings.vSyncCount = 0;
        QualitySettings.shadowDistance = escalaShadowDistance;
        QualitySettings.shadowCascades = 2;
        QualitySettings.shadowResolution = ShadowResolution.Medium;
    }

    private void Update()
    {
        if (!habilitarDynamicResolution)
        {
            return;
        }

        float deltaTime = Time.unscaledDeltaTime;
        if (deltaTime > targetFrameTime * 1.05f)
        {
            currentScale = Mathf.Max(minScaleFactor, currentScale - 0.05f);
        }
        else if (deltaTime < targetFrameTime * 0.90f)
        {
            currentScale = Mathf.Min(maxScaleFactor, currentScale + 0.02f);
        }

        ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
    }
}",
      "explicacao_didatica": "A placa de vídeo (GPU) estava gastando mais que o dobro do tempo ideal (36.11ms em vez de 16.7ms) para desenhar os pixels na tela. Isso acontece quando pedimos para ela calcular sombras super detalhadas ou desenhar em resolução máxima sem necessidade. O script reduz a resolução da imagem suavemente quando o jogo começa a engasgar e diminui a distância das sombras, aliviando o esforço da placa de vídeo para manter 60 quadros por segundo constantes."
    },
    {
      "tipo": "DrawCalls",
      "causa_raiz": "Pico de 2791 Draw Calls superando o orçamento de 2579 chamadas. Ocorre devido à instanciação de múltiplos materiais distintos e objetos repetidos renderizados sem o uso de MaterialPropertyBlock e GPU Instancing ativado.",
      "codigo_refatorado": "using UnityEngine;

[RequireComponent(typeof(MeshRenderer))]
public class InstancedPropController : MonoBehaviour
{
    private static readonly int ColorPropertyId = Shader.PropertyToID("_BaseColor");
    private static MaterialPropertyBlock propertyBlock;
    private MeshRenderer meshRenderer;

    [SerializeField] private Color objectColor = Color.white;

    private void Awake()
    {
        meshRenderer = GetComponent<MeshRenderer>();
        if (propertyBlock == null)
        {
            propertyBlock = new MaterialPropertyBlock();
        }
        ApplyColor();
    }

    public void SetColor(Color newColor)
    {
        objectColor = newColor;
        ApplyColor();
    }

    private void ApplyColor()
    {
        meshRenderer.GetPropertyBlock(propertyBlock);
        propertyBlock.SetColor(ColorPropertyId, objectColor);
        meshRenderer.SetPropertyBlock(propertyBlock);
    }
}",
      "explicacao_didatica": "Toda vez que você cria ou altera a cor de um objeto usando 'material.color', a Unity cria uma cópia inteira do material, impedindo que a GPU desenhe objetos parecidos de uma só vez (Draw Call). Com o MaterialPropertyBlock e marcando 'Enable GPU Instancing' no shader/material, a GPU consegue desenhar centenas de objetos idênticos ou coloridos em uma única chamada de desenho."
    }
  ],
  "dicas_level_design": "Como o limite de Draw Calls foi rompido (2791 contra 2579 suportados), implemente as seguintes diretrizes no Level Design: 1) Agrupamento em Atlas de Texturas: Combine texturas de adereços de cenário (props) em um único Atlas para que múltiplos objetos compartilhem o mesmo material; 2) Static Batching e Occlusion Culling: Marque todos os objetos estáticos do cenário como 'Static' e gere (bake) o Occlusion Culling para que objetos ocultos atrás de paredes não gastem chamadas de desenho nem preenchimento de GPU; 3) Sistema de LODs (Level of Detail): Configure pelo menos 3 níveis de detalhe (LOD0, LOD1 e Cull) para modelos com mais de 1000 polígonos, reduzindo a complexidade de malha à distância; 4) Modularidade com GPU Instancing: Use pedras, vegetação e estruturas modulares repetidas com materiais compatíveis com GPU Instancing ativado; 5) Iluminação Pré-calculada (Lightmaps): Evite múltiplas luzes dinâmicas 'Realtime' que multiplicam os draw calls por passagem; faça o Bake da iluminação estática."
}

